// Data-driven 100-day curriculum. Expand content here without touching UI.
export type QuizQ = { q: string; options: string[]; answer: number; why: string };
export type Phase = { id: number; name: string; topic: Topic; from: number; to: number; badge: string };
export type Topic = "Linux" | "Networking" | "Cloud" | "Containers" | "CI/CD" | "Kubernetes" | "IaC" | "Monitoring";
export type Day = {
  id: number;
  title: string;
  phase: Phase;
  minutes: number;
  objectives: string[];
  theory: string;
  hinglish: string;
  interview: string;
  example: string;
  commands: string[];
  task: string;
  steps: string[];
  validation: string;
  quiz: QuizQ[];
  troubleshooting: { scenario: string; fix: string };
  interviewQs: string[];
  detailed: boolean;
};

