const DEEP: Record<number, { theory: string; hinglish: string; example: string }> = {
  1: { theory: "A shell (like bash or zsh) is a program that reads the commands you type and asks the Linux kernel to run them. The terminal is just the window. Every command has a name, optional flags (like -l) and arguments (like a path).", hinglish: "Shell ek translator hai — aap command likhte ho, shell kernel ko bolta hai 'yeh kaam kar do'. Terminal sirf window hai, asli kaam shell karta hai.", example: "On-call engineers SSH into servers and use the shell to check what's wrong — no GUI exists on most servers." },
  2: { theory: "Linux has one tree starting at /. Absolute paths start with /, relative paths start from where you are. . means here, .. means parent, ~ means home.", hinglish: "Linux mein sab kuch ek ped (tree) jaisa hai jo / se shuru hota hai. Absolute path poora address hai, relative path 'yahan se kitna aage'.", example: "Config lives in /etc/nginx, logs in /var/log/nginx — knowing the tree saves minutes during outages." },
  3: { theory: "Files and directories are created with touch and mkdir, copied with cp, moved/renamed with mv and deleted with rm. There is no recycle bin, so -i (interactive) is your safety net.", hinglish: "rm se delete kiya toh wapas nahi aata — isliye -i lagao jab tak confident na ho.", example: "Deploy scripts create release folders like /opt/app/releases/2026-10-18 and switch a symlink." },
  4: { theory: "Every file has owner, group and others permissions: read (4), write (2), execute (1). chmod changes them; chown changes ownership.", hinglish: "Permission teen logon ke liye hoti hai — owner, group, baaki sab. 7 = sab kuch, 5 = padh aur chala sakte ho, 0 = kuch nahi.", example: "SSH refuses private keys readable by others — permissions are a real security control." },
  5: { theory: "Users identify who runs a process; groups bundle permissions. sudo lets permitted users run commands as root with an audit trail.", hinglish: "Har kaam kisi user ke naam se hota hai. Group ek team jaisa hai — team ko permission do, members ko mil jaati hai.", example: "Apps run under dedicated users like www-data so a compromise can't touch everything." },
  6: { theory: "A process is a running program with a PID. Signals are messages: SIGTERM asks politely, SIGKILL forces, SIGHUP often reloads config.", hinglish: "Process matlab chalta hua program. kill ek signal bhejta hai — 15 matlab 'please band ho jao', 9 matlab 'abhi band'.", example: "Kubernetes sends SIGTERM before killing pods so apps can finish requests." },
  7: { theory: "systemd starts and supervises services. Units describe what to run; systemctl controls them and journalctl shows their logs.", hinglish: "systemd server ka manager hai — kaunsa service chalega, crash ho toh restart karega.", example: "A failed nginx after config change is found with `systemctl status` in seconds." },
  8: { theory: "Package managers install software and dependencies from trusted repositories. apt (Debian/Ubuntu) and dnf (RHEL/Fedora) are the most common.", hinglish: "Package manager app store jaisa hai — dependency bhi khud le aata hai.", example: "Golden images install exact package versions for reproducible servers." },
  9: { theory: "df shows filesystem space, du shows directory usage, free shows memory, uptime shows load averages relative to CPU count.", hinglish: "Server slow? Pehle dekho — disk bhar gayi, RAM khatam, ya CPU busy.", example: "A full /var from logs is one of the most common production outages." },
  10: { theory: "Logs tell the story. journalctl reads systemd logs; classic files live in /var/log. Filtering with grep, time ranges and priorities finds the signal.", hinglish: "Logs server ki diary hai — kya hua, kab hua, sab likha hota hai.", example: "Incident timelines are built from log timestamps." },
  11: { theory: "SSH gives encrypted remote shells. Key-based auth uses a private key you keep and a public key placed on servers.", hinglish: "Public key taala hai jo server pe lagta hai, private key chaabi hai jo sirf aapke paas.", example: "Bastion hosts and SSH configs let teams reach private servers safely." },
  12: { theory: "Troubleshooting is a loop: observe symptoms, form a hypothesis, test it with one change, and record the result.", hinglish: "Andaaze se kuch mat badlo — pehle data lo, phir ek cheez test karo.", example: "SREs use USE method: Utilization, Saturation, Errors for every resource." },
  13: { theory: "Models split networking into layers so each problem can be isolated: physical/link, network (IP), transport (TCP/UDP), application (HTTP, DNS).", hinglish: "Layers ek building ki floors jaise hain — har floor ka alag kaam.", example: "'Ping works, website doesn't' tells you Layer 3 is fine." },
  14: { theory: "IPv4 addresses are 32-bit numbers. Private ranges are reused inside networks; NAT maps them to public IPs on the internet.", hinglish: "Private IP ghar ke andar ka room number, public IP ghar ka address.", example: "Cloud VPCs use 10.x private ranges for all internal traffic." },
};

function buildDay(i: number, r: Raw): Day {
  const id = i + 1;
  const phase = PHASES.find((p) => id >= p.from && id <= p.to)!;
  const [title, objective, commands, task, validation, q, tr] = r;
  const bank = BANK[phase.id]!;
  const offset = id - phase.from;
  const deep = DEEP[id];
  const quiz: QuizQ[] = [
    { q: q[0], options: q[1], answer: q[2], why: q[3] },
    bank[offset % bank.length]!,
    bank[(offset + 1) % bank.length]!,
  ];
  return {
    id,
    title,
    phase,
    minutes: deep ? 60 : 45,
    objectives: [objective, `Use ${commands[0]!.split(" ")[0]} and related tools hands-on`, "Explain the concept clearly in an interview"],
    theory: deep?.theory ?? `${objective} This day focuses on ${title.toLowerCase()} within ${phase.name}. Learn the concept, practice the key commands below, then validate your result.`,
    hinglish: deep?.hinglish ?? `Aaj ka focus: ${title}. Concept samjho, commands khud chala ke dekho, aur result verify karo — tabhi yaad rahega.`,
    interview: `${title}: ${objective} In practice I would ${task.charAt(0).toLowerCase() + task.slice(1)} and confirm success when ${validation.charAt(0).toLowerCase() + validation.slice(1)}`,
    example: deep?.example ?? `Teams rely on ${title.toLowerCase()} daily — e.g. "${tr[0]}" is a real issue engineers hit and fix with: ${tr[1]}`,
    commands,
    task,
    steps: [
      "Set up a safe practice environment (local VM, container, or the Playground).",
      ...commands.slice(0, 3).map((c) => `Run and understand: ${c}`),
      task,
      "Write down what you observed in your notes.",
    ],
    validation,
    quiz,
    troubleshooting: { scenario: tr[0], fix: tr[1] },
    interviewQs: [`Explain ${title.toLowerCase()} to a junior engineer.`, q[0], `How would you troubleshoot: ${tr[0]}`],
    detailed: !!deep,
  };
}

export const DAYS: Day[] = RAW.map((r, i) => buildDay(i, r));
export const getDay = (id: number) => DAYS.find((d) => d.id === id);
export const TOTAL_DAYS = DAYS.length;

